/* SUNSET RUN - lean PSG music + SFX player.
 *
 * The full NgpCraft driver is very capable but costs a lot of CPU per frame
 * (LFOs, ADSR, macros on every voice).  This player only does what the game
 * needs: four voices reading note streams, a simple decay envelope per note,
 * and a couple of SFX that temporarily take a channel.  It talks to the
 * Z80 through the same tiny polling program and mailbox as the NgpCraft
 * driver (Z80 code from NgpCraft sounds.c, MIT).
 *
 * Stream bytes (generated by tools/gen_music.py):
 *   1..51 note, then duration (vblanks)   0xFF rest, duration
 *   0xF0 n  attenuation (0 loud .. 15 off) 0xF4 n  instrument   0x00 end/loop
 * Noise voice: note byte = noise control value + 1.
 */
#include "ngpc_hw.h"
#include "ngpc_sys.h"
#include "player.h"

static const u8 z80drv[] = {
    0xC3, 0x13, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0xF3, 0x31, 0x00, 0x10,
    0x3A, 0x03, 0x00, 0xB7, 0x28, 0xFA, 0x47, 0x21, 0x04, 0x00,
    0x7E, 0x32, 0x01, 0x40, 0x32, 0x00, 0x40, 0x23,
    0x7E, 0x32, 0x01, 0x40, 0x32, 0x00, 0x40, 0x23,
    0x7E, 0x32, 0x01, 0x40, 0x32, 0x00, 0x40, 0x23,
    0x10, 0xE6, 0xAF, 0x32, 0x03, 0x00, 0x18, 0xD6
};
#define SND_COUNT (*(volatile u8 *)0x7003)
#define SND_BUF   ((volatile u8 *)0x7004)

/* instrument: vblanks per attenuation step, largest added attenuation */
typedef struct { u8 rate; u8 depth; } Inst;
static const Inst inst_tab[18] = {
    { 6u, 4u },   /*  0 clean          */
    { 1u, 15u },  /*  1 noise kick     */
    { 1u, 15u },  /*  2 noise hat      */
    { 2u, 15u },  /*  3 noise snare    */
    { 7u, 3u },   /*  4 bright lead    */
    { 5u, 3u },   /*  5 soft pad       */
    { 2u, 9u },   /*  6 pluck          */
    { 6u, 4u },   /*  7 bass           */
    { 3u, 8u },   /*  8 bell           */
    { 2u, 12u },  /*  9 zap            */
    { 8u, 3u },   /* 10 square brass   */
    { 8u, 3u },   /* 11 wide lead      */
    { 5u, 5u },   /* 12 deep bass      */
    { 3u, 6u },   /* 13 soft keys      */
    { 5u, 5u },   /* 14 chime pad      */
    { 2u, 12u },  /* 15 */
    { 2u, 12u },  /* 16 */
    { 6u, 4u }    /* 17 */
};

typedef struct {
    const u8 *ptr;
    const u8 *start;
    u16 wait;          /* vblanks until the next event */
    u16 div;           /* tone divider or noise control */
    u8  attn;          /* base attenuation */
    u8  add;           /* attenuation added by the decay so far */
    u8  acc;           /* vblanks towards the next decay step */
    u8  inst;
    u8  on;            /* note sounding */
    u8  trig;          /* noise: retrigger pending */
} Voice;

static Voice voice[4];
static u8 playing;
static u8 last_vbl;

/* desired and last-sent PSG state per channel (0..2 tone, 3 noise) */
static u16 want_div[4];
static u8  want_attn[4];
static u16 sent_div[4];
static u8  sent_attn[4];
static u8  noise_trig;

/* sound effects */
static u8  sfx_frames[4];
static u16 sfx_div[4];
static s8  sfx_step[4];
static u8  sfx_attn[4];
static u8  sfx_decay[4];      /* vblanks per attenuation step (0 = flat) */
static u8  sfx_age[4];

/* engine note: owns tone channel 2 (the songs keep only harmony there) */
static u16 eng_div;
static u8  eng_attn = 15u;
static u8  eng_on;

void player_engine(u16 div, u8 attn)
{
    eng_div = div;
    eng_attn = attn;
    eng_on = 1u;
}

void player_engine_off(void)
{
    eng_on = 0u;
}

void player_init(void)
{
    u8 i;
    volatile u8 *ram = (volatile u8 *)0x7000;
    HW_SOUNDCPU_CTRL = Z80_STOP;
    for (i = 0u; i < (u8)sizeof(z80drv); i++) {
        ram[i] = z80drv[i];
    }
    HW_SOUNDCPU_CTRL = Z80_START;
    for (i = 0u; i < 4u; i++) {
        want_div[i] = 0u;
        want_attn[i] = 15u;
        sent_div[i] = 0xFFFFu;
        sent_attn[i] = 0xFFu;
        sfx_frames[i] = 0u;
        voice[i].on = 0u;
    }
    playing = 0u;
    last_vbl = g_vb_counter;
}

void player_start(const u8 *v0, const u8 *v1, const u8 *v2, const u8 *vn)
{
    const u8 *p[4];
    u8 i;
    p[0] = v0; p[1] = v1; p[2] = v2; p[3] = vn;
    for (i = 0u; i < 4u; i++) {
        voice[i].ptr = p[i];
        voice[i].start = p[i];
        voice[i].wait = 0u;
        voice[i].attn = 2u;
        voice[i].inst = 0u;
        voice[i].on = 0u;
        voice[i].add = 0u;
        voice[i].acc = 0u;
        voice[i].trig = 0u;
    }
    playing = 1u;
    last_vbl = g_vb_counter;
}

void player_stop(void)
{
    u8 i;
    playing = 0u;
    for (i = 0u; i < 4u; i++) {
        voice[i].on = 0u;
    }
}

static void voice_events(Voice *v, u8 ch)
{
    u8 guard = 0u;
    while (v->wait == 0u && guard < 32u) {
        u8 b = *v->ptr++;
        guard++;
        if (b == 0x00u) {
            v->ptr = v->start;          /* loop */
            continue;
        }
        if (b == 0xF0u) {
            v->attn = *v->ptr++;
            continue;
        }
        if (b == 0xF4u) {
            v->inst = *v->ptr++;
            if (v->inst > 17u) v->inst = 0u;
            continue;
        }
        if (b == 0xFFu) {
            v->wait = *v->ptr++;
            v->on = 0u;
            continue;
        }
        if (b >= 0xF0u) {               /* unknown opcode: skip one byte */
            v->ptr++;
            continue;
        }
        v->wait = *v->ptr++;
        v->on = 1u;
        v->add = 0u;
        v->acc = 0u;
        if (ch == 3u) {
            v->div = (u16)((b - 1u) & 7u);
            v->trig = 1u;
        } else {
            v->div = note_div(b);
        }
    }
}

u16 note_div(u8 note)
{
    u8 idx = (u8)(note - 1u);
    if (idx > 50u) idx = 50u;
    return (u16)(((u16)(NOTE_TABLE[(u16)idx * 2u + 1u] & 0x3Fu) << 4) | (NOTE_TABLE[(u16)idx * 2u] & 0x0Fu));
}

static void flush(void)
{
    u8 n = 0u, ch;
    volatile u8 *buf = SND_BUF;
    if (SND_COUNT != 0u) {
        return;                         /* Z80 still busy: try next frame */
    }
    for (ch = 0u; ch < 4u && n < 5u; ch++) {
        u16 d = want_div[ch];
        u8 a = want_attn[ch];
        if (ch < 3u) {
            if (d == sent_div[ch] && a == sent_attn[ch]) continue;
            buf[0] = (u8)(0x80u | (u8)(ch << 5) | (u8)(d & 0x0Fu));
            buf[1] = (u8)((d >> 4) & 0x3Fu);
            buf[2] = (u8)(0x90u | (u8)(ch << 5) | (a & 0x0Fu));
        } else {
            if (!noise_trig && d == sent_div[3] && a == sent_attn[3]) continue;
            if (noise_trig || d != sent_div[3]) {
                buf[0] = (u8)(0xE0u | (u8)(d & 7u));
                buf[1] = (u8)(0xE0u | (u8)(d & 7u));
            } else {
                buf[0] = (u8)(0xF0u | (a & 0x0Fu));
                buf[1] = (u8)(0xF0u | (a & 0x0Fu));
            }
            buf[2] = (u8)(0xF0u | (a & 0x0Fu));
            noise_trig = 0u;
        }
        sent_div[ch] = d;
        sent_attn[ch] = a;
        buf += 3;
        n++;
    }
    if (n) {
        SND_COUNT = n;
    }
}

void player_update(void)
{
    u8 now = g_vb_counter;
    u8 e = (u8)(now - last_vbl);
    u8 ch;
    last_vbl = now;
    if (e > 8u) e = 8u;
    for (ch = 0u; ch < 4u; ch++) {
        u8 attn = 15u;
        u16 div = want_div[ch];
        if (playing) {
            Voice *v = &voice[ch];
            if (v->wait > e) {
                v->wait = (u16)(v->wait - e);
            } else {
                v->wait = 0u;
                voice_events(v, ch);
            }
            if (v->on) {
                /* decay: one attenuation step every in->rate vblanks, up to
                 * in->depth (counted, no division) */
                const Inst *in = &inst_tab[v->inst];
                if (v->add < in->depth) {
                    u8 acc = (u8)(v->acc + e);
                    while (acc >= in->rate && v->add < in->depth) {
                        acc = (u8)(acc - in->rate);
                        v->add++;
                    }
                    v->acc = acc;
                }
                attn = (u8)(v->attn + v->add);
                if (attn > 15u) attn = 15u;
                div = v->div;
                if (ch == 3u && v->trig) {
                    v->trig = 0u;
                    noise_trig = 1u;
                }
            }
        }
        if (ch == 2u && eng_on) {
            div = eng_div;
            attn = eng_attn;
        }
        if (sfx_frames[ch]) {
            /* an effect owns the channel */
            u8 a = sfx_attn[ch];
            if (sfx_decay[ch]) {
                u8 add = (u8)(sfx_age[ch] / sfx_decay[ch]);
                a = (u8)(a + add);
                if (a > 15u) a = 15u;
            }
            attn = a;
            div = sfx_div[ch];
            sfx_div[ch] = (u16)((s16)sfx_div[ch] + (s16)sfx_step[ch] * (s16)e);
            if (sfx_age[ch] < 250u) sfx_age[ch] = (u8)(sfx_age[ch] + e);
            sfx_frames[ch] = (sfx_frames[ch] > e) ? (u8)(sfx_frames[ch] - e) : 0u;
        }
        want_div[ch] = div;
        want_attn[ch] = attn;
    }
    flush();
}

void player_sfx_tone(u8 ch, u16 div, s8 step, u8 attn, u8 frames, u8 decay)
{
    sfx_div[ch] = div;
    sfx_step[ch] = step;
    sfx_attn[ch] = attn;
    sfx_frames[ch] = frames;
    sfx_decay[ch] = decay;
    sfx_age[ch] = 0u;
}

void player_sfx_noise(u8 ctrl, u8 attn, u8 frames, u8 decay)
{
    sfx_div[3] = ctrl;
    sfx_step[3] = 0;
    sfx_attn[3] = attn;
    sfx_frames[3] = frames;
    sfx_decay[3] = decay;
    sfx_age[3] = 0u;
    noise_trig = 1u;
}
